package com.marinainsaurralde.plango.data;
import static org.junit.Assert.*;import com.marinainsaurralde.plango.model.*;import org.junit.Test;import java.time.LocalDate;import java.util.*;
public class AgrupadorEventosTest{private Evento e(String id,Double lat,Double lon,String date,String tipo){return new Evento(id,id,date==null?null:date+" 00:00:00.0",date==null?null:date+" 23:59:00.0","CENTRO",tipo,true,lat,lon,"Lugar",null,null);}@Test public void groupsOnlyIdenticalValidCoordinates(){List<GrupoUbicacion>g=AgrupadorEventos.agrupar(Arrays.asList(e("1",40.4,-3.7,null,null),e("2",40.4,-3.7,null,null),e("3",40.5,-3.6,null,null),e("4",null,null,null,null),e("5",100.0,-3.0,null,null)));assertEquals(2,g.size());assertEquals(2,g.get(0).size());assertEquals(1,g.get(1).size());}@Test public void groupsReflectFilteredEvents(){List<Evento>all=Arrays.asList(e("today",40.4,-3.7,"2026-11-04",null),e("later",40.4,-3.7,"2026-11-08",null));FiltroEventos.Criterios today=new FiltroEventos.Criterios(FiltroEventos.Periodo.HOY,false,null);List<GrupoUbicacion>filtered=AgrupadorEventos.agrupar(FiltroEventos.aplicar(all,today,LocalDate.of(2026,11,4)));assertEquals(1,filtered.size());assertEquals(1,filtered.get(0).size());}@Test public void recognizesCategoriesAndFallsBack(){assertEquals(CategoriaCultural.MUSICA,CategoriaCultural.clasificar(e("1",1.0,1.0,null,"/Musica")));assertEquals(CategoriaCultural.TEATRO_ESPECTACULOS,CategoriaCultural.clasificar(e("2",1.0,1.0,null,"TeatroPerformance")));assertEquals(CategoriaCultural.OTRAS,CategoriaCultural.clasificar(e("3",1.0,1.0,null,null)));}}
